express-wildcard-task-new.test_js:
const assert = require('node:assert/strict');
const { once } = require('node:events');
const express = require('express');
const app = require('./solution.cjs')(express);
assert.equal(typeof app, 'function');
const route = app.router.stack.find(l =>
  l.route && l.route.path === '/{*splat}' && l.route.methods.get);
assert.ok(route, 'Missing named root-inclusive wildcard route');
(async () => {
  const server = app.listen(0, '127.0.0.1');
  try {
    // listen() is asynchronous: address() may be null until 'listening'.
    await once(server, 'listening');
    const address = server.address();
    assert.ok(address && Number.isInteger(address.port), 'Server has no assigned port');
    for (const pathname of ['/', '/nested/resource']) {
      const response = await fetch(
        `http://127.0.0.1:${address.port}${pathname}`,
        { signal: AbortSignal.timeout(5000) }
      );
      assert.equal(response.status, 200, pathname);
    }
    console.log('PASS Express 5 route handles root and nested paths');
  } finally {
    server.close();
  }
})().catch(e => { console.error(e); process.exitCode = 1; });

express-del-task-new.test_js:
const assert = require('node:assert/strict');
const { once } = require('node:events');
const express = require('express');
const app = require('./solution.cjs')(express);
assert.equal(typeof app, 'function');
const route = app.router.stack.find(l =>
  l.route && l.route.path === '/item' && l.route.methods.delete);
assert.ok(route, 'Missing DELETE /item');
(async () => {
  const server = app.listen(0, '127.0.0.1');
  try {
    // listen() is asynchronous: address() may be null until 'listening'.
    await once(server, 'listening');
    const address = server.address();
    assert.ok(address && Number.isInteger(address.port), 'Server has no assigned port');
    const response = await fetch(
      `http://127.0.0.1:${address.port}/item`,
      { method: 'DELETE', signal: AbortSignal.timeout(5000) }
    );
    assert.equal(response.status, 200);
    console.log('PASS Express 5 DELETE endpoint');
  } finally {
    server.close();
  }
})().catch(e => { console.error(e); process.exitCode = 1; });
